	@Test
	void refusesBeforeNativeAllocationWhenBuildScratchExceedsTheHardLimit() {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 20);
		assertThatThrownBy(() -> LmdbPagedCsfBaseBuilder.build(new SyntheticScanner(),
				LmdbAdjacencyCoverage.full(), account, 1L << 20, 1L << 16))
						.isInstanceOf(LmdbAdjacencyMemoryRefusedException.class)
						.hasMessageContaining("build-workspace reservation");
		assertThat(account.totalChargedBytes()).isZero();
	}

	/**
	 * The <em>authoritative</em> build's native sizing is exact: one byte below its measured high water refuses, and
	 * refusing leaks nothing.
	 * <p>
	 * The high water is measured with the node-predicate projection starved, so that it describes the primary build
	 * alone. That matters because on this fixture the projection's charge is what sets the overall peak, so measuring
	 * with it enabled and then subtracting one byte no longer refuses the build at all — the projection is optional
	 * derived state whose refusal is contained by design (see {@link #projectionRefusalKeepsTheAdjacencyBase()}).
	 * Before containment this test passed only because a projection refusal destroyed the whole build, which was the
	 * defect rather than the contract.
	 */
	@Test
	void refusesOneByteBelowTheMeasuredExactBuildHighWaterWithoutLeaking() throws IOException {
		LmdbAdjacencyMemoryAccount measuring = new LmdbAdjacencyMemoryAccount(1L << 30);
		measuring.refuseKindForTest(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_NATIVE);
		long exactHighWater;
		try (LmdbInMemoryAdjacencyIndex base = LmdbPagedCsfBaseBuilder.build(new SyntheticScanner(),
				LmdbAdjacencyCoverage.full(), measuring, 1L << 20, 1L << 16)) {
			assertThat(base.nodePredicateIndexOrNull()).isNull();
			exactHighWater = measuring.highWaterBytes();
			assertThat(exactHighWater).isPositive();
		}
		assertThat(measuring.totalChargedBytes()).isZero();

		LmdbAdjacencyMemoryAccount refused = new LmdbAdjacencyMemoryAccount(exactHighWater - 1);
		refused.refuseKindForTest(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_NATIVE);
		assertThatThrownBy(() -> LmdbPagedCsfBaseBuilder.build(new SyntheticScanner(),
				LmdbAdjacencyCoverage.full(), refused, 1L << 20, 1L << 16))
						.isInstanceOf(LmdbAdjacencyMemoryRefusedException.class);
		assertThat(refused.totalChargedBytes()).isZero();
	}

	/**
	 * The node-predicate projection is optional derived state. Refusing its memory must cost only the projection, never
	 * the authoritative adjacency base.
	 * <p>
	 * Before containment the refusal propagated out of the whole build and left the store in
	 * {@code MaintenanceState.MEMORY_REFUSED}, which — unlike the neighbouring abort path — never retriggers, so a
	 * store near its cap permanently lost all adjacency because a small sidecar did not fit.
	 */
	@Test
	void projectionRefusalKeepsTheAdjacencyBase() throws IOException {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		account.refuseKindForTest(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_NATIVE);

		long chargedWithoutProjection;
		try (LmdbInMemoryAdjacencyIndex base = LmdbPagedCsfBaseBuilder.build(new SyntheticScanner(),
				LmdbAdjacencyCoverage.full(), account, 1L << 20, 1L << 16)) {
			// The base survives, in the paged format, simply without the projection.
			assertThat(base.nodePredicateIndexOrNull()).isNull();
			assertThat(base.supportsPredicateEnumeration(LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT)).isFalse();
			assertThatThrownBy(base::nodePredicateIndex).isInstanceOf(IllegalStateException.class);

			// The primary index is fully usable.
			long predicate = base.bindPredicate(id(1, 5));
			assertThat(LmdbAdjacencyRunCodec.edgeCount(base.arenaCatalog(),
					base.findRunByOrdinal(id(1, 10), 0, predicate, null))).isEqualTo(2);

			// No partial charge from the refused attempt is stranded under either projection kind.
			chargedWithoutProjection = account.totalChargedBytes();
			assertThat(account.chargedBytes(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_NATIVE)).isZero();
			assertThat(account.chargedBytes(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_JAVA)).isZero();
		}
		assertThat(account.totalChargedBytes()).isZero();

		// A build that does keep the projection charges it to the projection's own kinds, and nothing else moves.
		LmdbAdjacencyMemoryAccount withProjection = new LmdbAdjacencyMemoryAccount(1L << 30);
		try (LmdbInMemoryAdjacencyIndex base = LmdbPagedCsfBaseBuilder.build(new SyntheticScanner(),
				LmdbAdjacencyCoverage.full(), withProjection, 1L << 20, 1L << 16)) {
			long projectionNative = withProjection
					.chargedBytes(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_NATIVE);
			long projectionJava = withProjection
					.chargedBytes(LmdbAdjacencyMemoryAccount.MemoryKind.NODE_PREDICATE_JAVA);

			// The native charge is exact: the projection's build budget asserts itself exhausted.
			assertThat(projectionNative).isEqualTo(base.nodePredicateIndex().nativeBytes()).isPositive();
			// The metadata charge comes from the build plan, which is conservative relative to the finished index's
			// own model, and the surplus stays charged rather than being released. Milestone A3 reports the charged
			// figure rather than modeledJavaBytes(), because the charge is what consumes the cap.
			assertThat(projectionJava).isGreaterThanOrEqualTo(base.nodePredicateIndex().modeledJavaBytes());

			// Everything outside the two projection kinds matches the refused build byte for byte.
			assertThat(withProjection.totalChargedBytes() - projectionNative - projectionJava)
					.isEqualTo(chargedWithoutProjection);
		}
		assertThat(withProjection.totalChargedBytes()).isZero();
	}

	@Test
	void storesRawContextFibresInCsf() throws IOException {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		try (LmdbInMemoryAdjacencyIndex base = LmdbPagedCsfBaseBuilder.build(new SyntheticScanner(),
				LmdbAdjacencyCoverage.full(), account, 1L << 20, 1L << 16)) {
			assertThat(base.supportsPredicateEnumeration(LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT)).isTrue();
			assertThat(base.supportsPredicateEnumeration(LmdbAdjacencyPlane.PLANE_OUTGOING_INFERRED)).isTrue();
			assertThat(base.supportsPredicateEnumeration(LmdbAdjacencyPlane.PLANE_INCOMING_EXPLICIT)).isFalse();
			assertThat(base.statementCount()).isEqualTo(4);
			assertThat(base.incidenceCount()).isEqualTo(8);

			long predicate = base.bindPredicate(id(1, 5));
			assertThat(predicate).isZero();
			long outgoing = base.findRunByOrdinal(id(1, 10), 0, predicate, null);
			assertThat(base.arenaCatalog().isCsfHandle(outgoing)).isTrue();
			assertThat(LmdbAdjacencyRunCodec.edgeCount(base.arenaCatalog(), outgoing)).isEqualTo(2);
			assertThat(LmdbAdjacencyRunCodec.contextAt(base.arenaCatalog(), base.contextCatalog(), outgoing, 1))
					.isEqualTo(id(1, 4));

			long incoming = base.findRunByOrdinal(id(1, 20), 1, predicate, null);
			assertThat(LmdbAdjacencyRunCodec.edgeCount(base.arenaCatalog(), incoming)).isEqualTo(2);
			long inferred = base.findRunByOrdinal(id(1, 10), 2, predicate, null);
			assertThat(LmdbAdjacencyRunCodec.neighborAt(base.arenaCatalog(), inferred, 0)).isEqualTo(id(1, 22));
			long inferredIncoming = base.findRunByOrdinal(id(1, 22), 3, predicate, null);
			assertThat(LmdbAdjacencyRunCodec.neighborAt(base.arenaCatalog(), inferredIncoming, 0))
					.isEqualTo(id(1, 10));

			ImmutablePagedQuadCsfIndex.KeyDomain keys = base.keyDomain(predicate, 0);
			assertThat(keys.keyCount()).isEqualTo(2);
			assertThat(keys.keyAt(0)).isEqualTo(id(1, 10));
			assertThat(keys.keyAt(1)).isEqualTo(id(1, 12));
			assertThat(base.findRunByOrdinal(id(1, 999), 0, predicate, null))
					.isEqualTo(LmdbInMemoryAdjacencyIndex.NOT_FOUND);
		}
		assertThat(account.totalChargedBytes()).isZero();
	}

